import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const locales = ["fr", "en", "de", "it"] as const
export type Locale = (typeof locales)[number]
export const defaultLocale: Locale = "fr"

export const localeNames: Record<Locale, string> = {
  fr: "Français",
  en: "English",
  de: "Deutsch",
  it: "Italiano",
}

export const localeShort: Record<Locale, string> = {
  fr: "FR",
  en: "EN",
  de: "DE",
  it: "IT",
}

export const ogLocales: Record<Locale, string> = {
  fr: "fr_CH",
  en: "en_US",
  de: "de_CH",
  it: "it_CH",
}

export function isLocale(value: string): value is Locale {
  return (locales as readonly string[]).includes(value)
}

import "server-only"

import { defaultLocale, type Locale } from "./config"

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Dictionary = Record<string, any>

const dictionaries: Record<string, () => Promise<Dictionary>> = {
  fr: () => import("./fr.json").then((m) => m.default),
  en: () => import("./en.json").then((m) => m.default),
  de: () => import("./de.json").then((m) => m.default),
  it: () => import("./it.json").then((m) => m.default),
}

export async function getDictionary(locale: Locale): Promise<Dictionary> {
  const loader = dictionaries[locale] ?? dictionaries[defaultLocale]
  return loader()
}

export function t(dictionary: Dictionary, key: string): string {
  const value = key
    .split(".")
    .reduce<unknown>((acc, part) => {
      if (acc && typeof acc === "object" && part in (acc as Record<string, unknown>)) {
        return (acc as Record<string, unknown>)[part]
      }
      return undefined
    }, dictionary)

  return typeof value === "string" ? value : key
}

export function tList(dictionary: Dictionary, key: string): string[] {
  const value = key.split(".").reduce<unknown>((acc, part) => {
    if (acc && typeof acc === "object" && part in (acc as Record<string, unknown>)) {
      return (acc as Record<string, unknown>)[part]
    }
    return undefined
  }, dictionary)

  return Array.isArray(value) ? (value as string[]) : []
}

export function tNode<T = unknown>(dictionary: Dictionary, key: string): T | undefined {
  const value = key.split(".").reduce<unknown>((acc, part) => {
    if (acc && typeof acc === "object" && part in (acc as Record<string, unknown>)) {
      return (acc as Record<string, unknown>)[part]
    }
    return undefined
  }, dictionary)

  return value as T | undefined
}

export { type Locale, locales, defaultLocale, localeNames, localeShort, ogLocales, isLocale } from "./config"

import { NextResponse, type NextRequest } from "next/server"
import { locales, defaultLocale } from "@/lib/i18n/config"

function getLocale(request: NextRequest): string {
  const cookieLocale = request.cookies.get("NEXT_LOCALE")?.value
  if (cookieLocale && (locales as readonly string[]).includes(cookieLocale)) {
    return cookieLocale
  }

  const acceptLang = request.headers.get("accept-language")
  if (acceptLang) {
    const preferred = acceptLang
      .split(",")
      .map((part) => part.split(";")[0].trim().toLowerCase().split("-")[0])

    for (const lang of preferred) {
      if ((locales as readonly string[]).includes(lang)) {
        return lang
      }
    }
  }

  return defaultLocale
}

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl

  if (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api") ||
    pathname.includes(".") ||
    pathname === "/robots.txt" ||
    pathname === "/sitemap.xml"
  ) {
    return NextResponse.next()
  }

  const pathnameHasLocale = locales.some(
    (locale) => pathname === `/${locale}` || pathname.startsWith(`/${locale}/`),
  )

  if (pathnameHasLocale) return NextResponse.next()

  const locale = getLocale(request)
  const url = request.nextUrl.clone()
  url.pathname = `/${locale}${pathname === "/" ? "" : pathname}`

  const response = NextResponse.redirect(url)
  response.cookies.set("NEXT_LOCALE", locale, { maxAge: 60 * 60 * 24 * 365, path: "/" })
  return response
}

export const config = {
  matcher: ["/((?!_next|api|.*\\..*).*)"],
}

interface JsonLdProps {
  data: Record<string, unknown>
}

export function JsonLd({ data }: JsonLdProps) {
  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
    />
  )
}

export function organizationJsonLd({
  name,
  url,
  logo,
  phone,
  email,
  address,
}: {
  name: string
  url: string
  logo?: string
  phone?: string
  email?: string
  address?: { street: string; city: string; postalCode: string; country: string }
}) {
  return {
    "@context": "https://schema.org",
    "@type": "LocalBusiness",
    "@id": `${url}/#organization`,
    name,
    url,
    ...(logo && { logo }),
    ...(phone && { telephone: phone }),
    ...(email && { email }),
    ...(address && {
      address: {
        "@type": "PostalAddress",
        streetAddress: address.street,
        addressLocality: address.city,
        postalCode: address.postalCode,
        addressCountry: address.country,
      },
    }),
  }
}

export function breadcrumbJsonLd(items: { name: string; url: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: item.url,
    })),
  }
}

export function faqJsonLd(items: { question: string; answer: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  }
}

export function serviceJsonLd({
  name,
  description,
  provider,
  url,
}: {
  name: string
  description: string
  provider: { name: string; url: string }
  url: string
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    url,
    provider: {
      "@type": "LocalBusiness",
      name: provider.name,
      url: provider.url,
    },
  }
}

"use client"

import { motion, type Variants } from "motion/react"
import type { ReactNode } from "react"
import { cn } from "@/lib/utils"

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0 },
}

const fadeIn: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
}

const scaleIn: Variants = {
  hidden: { opacity: 0, scale: 0.95 },
  visible: { opacity: 1, scale: 1 },
}

export interface AnimationProps {
  children: ReactNode
  delay?: number
  className?: string
}

export function FadeUp({ children, delay = 0, className }: AnimationProps) {
  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, margin: "-50px" }}
      variants={fadeUp}
      transition={{ duration: 0.5, delay, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function FadeIn({ children, delay = 0, className }: AnimationProps) {
  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, margin: "-50px" }}
      variants={fadeIn}
      transition={{ duration: 0.6, delay, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function ScaleIn({ children, delay = 0, className }: AnimationProps) {
  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, margin: "-50px" }}
      variants={scaleIn}
      transition={{ duration: 0.5, delay, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function StaggerContainer({
  children,
  className,
  staggerDelay = 0.1,
}: {
  children: ReactNode
  className?: string
  staggerDelay?: number
}) {
  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, margin: "-50px" }}
      variants={{
        visible: { transition: { staggerChildren: staggerDelay } },
      }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function StaggerItem({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <motion.div variants={fadeUp} transition={{ duration: 0.5, ease: "easeOut" }} className={cn(className)}>
      {children}
    </motion.div>
  )
}

export function HeroAnimation({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function ImageReveal({ children, delay = 0, className }: AnimationProps) {
  return (
    <motion.div
      initial={{ opacity: 0, scale: 1.05 }}
      whileInView={{ opacity: 1, scale: 1 }}
      viewport={{ once: true, margin: "-50px" }}
      transition={{ duration: 0.7, delay, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

"use client"

import { motion } from "motion/react"
import type { ReactNode } from "react"
import { cn } from "@/lib/utils"

export interface RevealProps {
  children: ReactNode
  delay?: number
  y?: number
  className?: string
}

export function Reveal({
  children,
  delay = 0,
  y = 24,
  className,
}: RevealProps) {
  return (
    <motion.div
      className={className ? cn(className) : undefined}
      initial={{ opacity: 0, y }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-80px" }}
      transition={{ duration: 0.6, delay, ease: [0.21, 0.47, 0.32, 0.98] }}
    >
      {children}
    </motion.div>
  )
}

"use client"

import { useState, useRef } from "react"
import { Share2, Copy, Check } from "lucide-react"
import { cn } from "@/lib/utils"

export interface ShareButtonProps {
  title: string
  text: string
  shareLabel?: string
  copiedLabel?: string
  url?: string
  className?: string
}

export function ShareButton({
  title,
  text,
  shareLabel = "Share",
  copiedLabel = "Link copied",
  url,
  className,
}: ShareButtonProps) {
  const [copied, setCopied] = useState(false)
  const sharing = useRef(false)

  const handleShare = async () => {
    if (sharing.current) return
    sharing.current = true

    const shareUrl = url ?? window.location.href

    try {
      if (navigator.share) {
        await navigator.share({ title, text, url: shareUrl })
      } else {
        await navigator.clipboard.writeText(`${text} : ${shareUrl}`)
        setCopied(true)
        setTimeout(() => setCopied(false), 2000)
      }
    } catch {
      /* user cancelled — ignore */
    } finally {
      sharing.current = false
    }
  }

  return (
    <button
      type="button"
      onClick={handleShare}
      className={cn(
        "inline-flex items-center gap-2 text-sm font-semibold text-primary transition-colors hover:text-primary/80",
        className,
      )}
    >
      {copied ? (
        <>
          <Check className="h-4 w-4" />
          {copiedLabel}
        </>
      ) : (
        <>
          <Share2 className="h-4 w-4" />
          {shareLabel}
        </>
      )}
    </button>
  )
}

"use client"

import { useEffect, useState } from "react"
import { ArrowUp } from "lucide-react"

export interface BackToTopProps {
  ariaLabel?: string
}

export function BackToTop({ ariaLabel = "Back to top" }: BackToTopProps) {
  const [show, setShow] = useState(false)

  useEffect(() => {
    const onScroll = () => setShow(window.scrollY > 400)
    onScroll()
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  if (!show) return null

  return (
    <button
      type="button"
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      className="fixed bottom-6 right-6 z-50 flex h-11 w-11 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-lg transition-all hover:bg-primary/90 hover:scale-105 focus-visible:ring-3 focus-visible:ring-ring/40"
      aria-label={ariaLabel}
    >
      <ArrowUp className="h-5 w-5" aria-hidden="true" />
    </button>
  )
}

import {
  type SectionVariant,
  sectionVariantClasses,
} from "@/lib/section-variants"
import { cn } from "@/lib/utils"

export interface SectionHeadingProps {
  eyebrow?: string
  title: string
  subtitle?: string
  align?: "center" | "left"
  as?: "h1" | "h2" | "h3"
  variant?: SectionVariant
  /** @deprecated Use variant="primary" instead */
  inverted?: boolean
  className?: string
}

export function SectionHeading({
  eyebrow,
  title,
  subtitle,
  align = "center",
  as: Tag = "h2",
  variant: variantProp,
  inverted = false,
  className,
}: SectionHeadingProps) {
  const variant = variantProp ?? (inverted ? "primary" : "default")
  const colors = sectionVariantClasses[variant]
  const isDark = variant === "primary" || variant === "secondary"

  return (
    <div
      className={cn(
        "max-w-3xl",
        align === "center" ? "mx-auto text-center" : "text-left",
        className,
      )}
    >
      {eyebrow ? (
        <>
          <span
            className={cn(
              "mb-3 inline-block text-sm font-semibold uppercase tracking-[0.18em]",
              colors.eyebrow,
            )}
          >
            {eyebrow}
          </span>
          <span
            className={cn(
              "mb-4 block h-0.5 w-10 rounded-full",
              isDark ? "bg-primary-foreground/40" : "bg-secondary",
              align === "center" ? "mx-auto" : "",
            )}
          />
        </>
      ) : null}
      <Tag
        className={cn(
          "text-pretty font-heading text-3xl font-bold leading-tight tracking-tight sm:text-4xl",
          colors.heading,
        )}
      >
        {title}
      </Tag>
      {subtitle ? (
        <p
          className={cn(
            "mt-4 text-lg leading-relaxed text-pretty",
            colors.body,
          )}
        >
          {subtitle}
        </p>
      ) : null}
    </div>
  )
}

"use client"

import { useState } from "react"
import Image from "next/image"
import { ImageIcon } from "lucide-react"
import { cn } from "@/lib/utils"

export interface ImageWithFallbackProps {
  src: string
  alt: string
  width?: number
  height?: number
  fill?: boolean
  priority?: boolean
  sizes?: string
  quality?: number
  className?: string
  fallbackLabel?: string
}

export function ImageWithFallback({
  src,
  alt,
  width,
  height,
  fill = false,
  priority = false,
  sizes,
  quality,
  className,
  fallbackLabel = "Photo coming soon",
}: ImageWithFallbackProps) {
  const [errored, setErrored] = useState(false)

  if (errored || !src) {
    return (
      <div
        className={cn(
          "flex flex-col items-center justify-center gap-2 bg-muted text-muted-foreground",
          fill ? "absolute inset-0 h-full w-full" : "",
          className,
        )}
        style={fill ? undefined : { width, height }}
        role="img"
        aria-label={alt}
      >
        <ImageIcon className="h-8 w-8 opacity-50" aria-hidden="true" />
        <span className="text-xs font-medium">{fallbackLabel}</span>
      </div>
    )
  }

  return (
    <Image
      src={src}
      alt={alt}
      width={fill ? undefined : width}
      height={fill ? undefined : height}
      fill={fill}
      priority={priority}
      loading={priority ? undefined : "lazy"}
      sizes={sizes}
      quality={quality ?? (priority ? 85 : 75)}
      onError={() => setErrored(true)}
      className={cn(fill ? "object-cover" : "", className)}
    />
  )
}

"use client"

import { useState, useCallback, useEffect } from "react"
import Image from "next/image"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

export interface LightboxProps {
  src: string
  alt: string
  width?: number
  height?: number
  fill?: boolean
  sizes?: string
  className?: string
  enlargeLabel?: string
  closeLabel?: string
  children?: React.ReactNode
}

export function Lightbox({
  src,
  alt,
  width,
  height,
  fill,
  sizes,
  className,
  enlargeLabel = "Click to enlarge",
  closeLabel = "Close",
  children,
}: LightboxProps) {
  const [open, setOpen] = useState(false)
  const openModal = useCallback(() => setOpen(true), [])
  const closeModal = useCallback(() => setOpen(false), [])

  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeModal()
    }
    document.addEventListener("keydown", onKey)
    document.body.style.overflow = "hidden"
    return () => {
      document.removeEventListener("keydown", onKey)
      document.body.style.overflow = ""
    }
  }, [open, closeModal])

  return (
    <>
      <button
        type="button"
        onClick={openModal}
        className={cn(
          "group/lightbox relative block w-full cursor-zoom-in overflow-hidden border-0 bg-transparent p-0",
          className,
        )}
        aria-label={alt ? `${enlargeLabel} : ${alt}` : enlargeLabel}
      >
        {children ?? (
          <Image
            src={src}
            alt={alt}
            fill={fill}
            width={!fill ? width : undefined}
            height={!fill ? height : undefined}
            sizes={sizes}
            className="object-cover transition-transform duration-500 group-hover/lightbox:scale-105"
          />
        )}
        <span className="pointer-events-none absolute inset-0 flex items-center justify-center bg-foreground/0 transition-colors group-hover/lightbox:bg-foreground/10">
          <span className="rounded-full bg-foreground/50 px-3 py-1.5 text-xs font-medium text-background opacity-0 backdrop-blur-sm transition-opacity group-hover/lightbox:opacity-100">
            {enlargeLabel}
          </span>
        </span>
      </button>

      {open && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 p-4 backdrop-blur-sm"
          role="dialog"
          aria-modal="true"
          onClick={closeModal}
        >
          <button
            type="button"
            onClick={closeModal}
            className="absolute top-4 right-4 z-10 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white backdrop-blur-sm transition-colors hover:bg-white/20"
            aria-label={closeLabel}
          >
            <X className="h-5 w-5" />
          </button>
          <img
            src={src}
            alt={alt}
            className="max-h-[90vh] max-w-[90vw] rounded-lg object-contain"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </>
  )
}

import Link from "next/link"
import { cn } from "@/lib/utils"

export type CtaVariant = "primary" | "secondary" | "outline" | "onDark"
export type CtaSize = "default" | "lg"

const variantClasses: Record<CtaVariant, string> = {
  primary:
    "bg-primary text-primary-foreground hover:bg-primary/90 focus-visible:ring-primary/40",
  secondary:
    "bg-secondary text-secondary-foreground hover:bg-secondary/90 focus-visible:ring-secondary/40",
  outline:
    "border border-border bg-background text-foreground hover:bg-muted focus-visible:ring-ring/40",
  onDark:
    "bg-background text-foreground hover:bg-background/90 focus-visible:ring-background/50",
}

const sizeClasses: Record<CtaSize, string> = {
  default: "h-11 px-5 text-sm",
  lg: "h-12 px-7 text-base",
}

const base =
  "inline-flex items-center justify-center gap-2 rounded-lg font-semibold whitespace-nowrap transition-colors outline-none focus-visible:ring-3 disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0"

export interface CtaButtonProps {
  children: React.ReactNode
  variant?: CtaVariant
  size?: CtaSize
  className?: string
}

export function CtaLink({
  href,
  children,
  variant = "primary",
  size = "default",
  className,
}: CtaButtonProps & { href: string }) {
  return (
    <Link
      href={href}
      className={cn(base, variantClasses[variant], sizeClasses[size], className)}
    >
      {children}
    </Link>
  )
}

export function CtaExternal({
  href,
  children,
  variant = "primary",
  size = "default",
  className,
}: CtaButtonProps & { href: string }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className={cn(base, variantClasses[variant], sizeClasses[size], className)}
    >
      {children}
    </a>
  )
}

import Link from "next/link"
import { ChevronRight } from "lucide-react"
import { cn } from "@/lib/utils"

export interface Crumb {
  label: string
  href: string
}

export interface BreadcrumbProps {
  homeLabel: string
  items: Crumb[]
  className?: string
}

export function Breadcrumb({ homeLabel, items, className }: BreadcrumbProps) {
  const all: Crumb[] = [{ label: homeLabel, href: "/" }, ...items]

  return (
    <nav aria-label="Breadcrumb" className={cn("container-premium pt-24 md:pt-28", className)}>
      <ol className="flex flex-wrap items-center gap-1 text-sm text-muted-foreground">
        {all.map((crumb, i) => {
          const isLast = i === all.length - 1
          return (
            <li key={crumb.href} className="flex items-center gap-1">
              {isLast ? (
                <span className="font-medium text-foreground" aria-current="page">
                  {crumb.label}
                </span>
              ) : (
                <>
                  <Link href={crumb.href} className="transition-colors hover:text-primary">
                    {crumb.label}
                  </Link>
                  <ChevronRight className="h-4 w-4" aria-hidden="true" />
                </>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

"use client"

import * as React from "react"
import { CheckIcon, ChevronRightIcon, CircleIcon } from "lucide-react"
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"

function DropdownMenu({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Root>) {
  return <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return (
    <DropdownMenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
  )
}

function DropdownMenuTrigger({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Trigger>) {
  return (
    <DropdownMenuPrimitive.Trigger
      data-slot="dropdown-menu-trigger"
      {...props}
    />
  )
}

function DropdownMenuContent({
  className,
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Content>) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Content
        data-slot="dropdown-menu-content"
