"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

export type NewsletterProps = Omit<React.ComponentPropsWithoutRef<"section">, "onSubmit"> & {
  title?: string;
  description?: string;
  eyebrow?: string;
  placeholder?: string;
  buttonLabel?: string;
  privacyText?: string;
  loading?: boolean;
  successMessage?: string;
  errorMessage?: string;
  disabled?: boolean;
  icon?: React.ReactNode;
  validationErrorMessage?: string;
  submitErrorMessage?: string;
  emailLabel?: string;
  loadingLabel?: string;
  onSubmit: (email: string) => void | Promise<void>;
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function Newsletter({
  title = "Stay in the loop",
  description = "Get product updates and practical tips delivered to your inbox.",
  eyebrow,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  privacyText,
  loading = false,
  successMessage,
  errorMessage,
  disabled = false,
  icon,
  validationErrorMessage = "Please enter a valid email address.",
  submitErrorMessage = "Something went wrong. Please try again.",
  emailLabel = "Email address",
  loadingLabel = "Submitting...",
  onSubmit,
  className,
  ...props
}: NewsletterProps) {
  const baseId = React.useId();
  const inputId = `${baseId}-email`;
  const helperId = `${baseId}-helper`;
  const errorId = `${baseId}-error`;
  const successId = `${baseId}-success`;

  const [email, setEmail] = React.useState("");
  const [validationError, setValidationError] = React.useState<string>();
  const [submitError, setSubmitError] = React.useState<string>();
  const [showStatus, setShowStatus] = React.useState(true);
  const [submitting, setSubmitting] = React.useState(false);

  const hasError = Boolean(validationError || submitError || (showStatus && errorMessage));
  const inlineError = validationError || submitError || (showStatus ? errorMessage : undefined);
  const inlineSuccess = !inlineError && showStatus ? successMessage : undefined;
  const isLoading = loading || submitting;
  const isDisabled = disabled || isLoading;

  const describedBy = [privacyText ? helperId : undefined, inlineError ? errorId : undefined]
    .filter(Boolean)
    .join(" ");

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (isDisabled) {
      return;
    }

    const normalizedEmail = email.trim();

    if (!EMAIL_REGEX.test(normalizedEmail)) {
      setShowStatus(false);
      setValidationError(validationErrorMessage);
      return;
    }

    setShowStatus(true);
    setValidationError(undefined);
    setSubmitError(undefined);

    try {
      setSubmitting(true);
      await Promise.resolve(onSubmit(normalizedEmail));
    } catch {
      setSubmitError(submitErrorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <section
      className={cn(
        "w-full rounded-xl border border-border bg-background p-5 shadow-sm sm:p-6",
        className,
      )}
      {...props}
    >
      <div className="space-y-2">
        {eyebrow ? (
          <p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">
            {eyebrow}
          </p>
        ) : null}
        <div className="flex items-center gap-2">
          {icon ? <span className="text-muted-foreground">{icon}</span> : null}
          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        </div>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>

      <form className="mt-4" onSubmit={handleSubmit} noValidate>
        <label className="sr-only" htmlFor={inputId}>
          {emailLabel}
        </label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <input
            id={inputId}
            type="email"
            name="email"
            autoComplete="email"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              setValidationError(undefined);
              setSubmitError(undefined);
              setShowStatus(false);
            }}
            placeholder={placeholder}
            disabled={isDisabled}
            aria-invalid={hasError}
            aria-describedby={describedBy || undefined}
            className="h-11 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
          />
          <button
            type="submit"
            disabled={isDisabled}
            className="inline-flex h-11 shrink-0 items-center justify-center rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isLoading ? loadingLabel : buttonLabel}
          </button>
        </div>

        {privacyText ? (
          <p className="mt-3 text-xs text-muted-foreground" id={helperId}>
            {privacyText}
          </p>
        ) : null}

        {inlineError ? (
          <p className="mt-2 text-sm text-red-600 dark:text-red-400" id={errorId} role="alert" aria-live="assertive">
            {inlineError}
          </p>
        ) : null}

        {inlineSuccess ? (
          <p className="mt-2 text-sm text-emerald-700 dark:text-emerald-400" id={successId} role="status" aria-live="polite">
            {inlineSuccess}
          </p>
        ) : null}
      </form>
    </section>
  );
}

"use client";

import * as React from "react";

import { Newsletter } from "@/components/forms/newsletter";

export function NewsletterExample() {
  const [loading, setLoading] = React.useState(false);
  const [successMessage, setSuccessMessage] = React.useState<string>();
  const [errorMessage, setErrorMessage] = React.useState<string>();

  async function handleSubmit(email: string) {
    setLoading(true);
    setSuccessMessage(undefined);
    setErrorMessage(undefined);

    try {
      await new Promise((resolve) => setTimeout(resolve, 600));
      setSuccessMessage(`Thanks for subscribing, ${email}!`);
    } catch {
      setErrorMessage("Could not subscribe right now. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Newsletter
      eyebrow="Newsletter"
      title="Build better products"
      description="A monthly digest with experiments, release notes, and UX insights."
      placeholder="name@company.com"
      buttonLabel="Join now"
      privacyText="No spam. Unsubscribe any time."
      loading={loading}
      successMessage={successMessage}
      errorMessage={errorMessage}
      onSubmit={handleSubmit}
    />
  );
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { cn } from "@/lib/utils"

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void
    dataLayer?: Object[]
  }
}

export interface ConsentState {
  necessary: boolean
  analytics: boolean
  marketing: boolean
}

const DEFAULT_CONSENT: ConsentState = {
  necessary: true,
  analytics: false,
  marketing: false,
}

function ensureGtag() {
  if (typeof window === "undefined") return
  window.gtag =
    window.gtag ||
    ((...args: unknown[]) => {
      window.dataLayer = window.dataLayer || []
      window.dataLayer.push(args)
    })
}

function serialize(state: ConsentState): string {
  return JSON.stringify(state)
}

function deserialize(raw: string): ConsentState | null {
  try {
    const parsed = JSON.parse(raw)
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof parsed.necessary === "boolean" &&
      typeof parsed.analytics === "boolean" &&
      typeof parsed.marketing === "boolean"
    ) {
      return parsed as ConsentState
    }
    return null
  } catch {
    return null
  }
}

function applyConsent(state: ConsentState) {
  ensureGtag()
  window.gtag?.("consent", "update", {
    ad_storage: state.marketing ? "granted" : "denied",
    analytics_storage: state.analytics ? "granted" : "denied",
    ad_user_data: state.marketing ? "granted" : "denied",
    ad_personalization: state.marketing ? "granted" : "denied",
  })
}

export interface CookieBannerProps {
  consentKey?: string
  manageEvent?: string
  text: string
  acceptAllLabel: string
  acceptSelectionLabel: string
  rejectLabel: string
  policyLabel: string
  privacyHref: string
  necessaryTitle: string
  necessaryDescription: string
  analyticsTitle: string
  analyticsDescription: string
  marketingTitle: string
  marketingDescription: string
  dialogLabel?: string
  showAnalytics?: boolean
  showMarketing?: boolean
  hidden?: boolean
}

export function CookieBanner({
  consentKey = "cookie-consent",
  manageEvent = "manage-cookies",
  text,
  acceptAllLabel,
  acceptSelectionLabel,
  rejectLabel,
  policyLabel,
  privacyHref,
  necessaryTitle,
  necessaryDescription,
  analyticsTitle,
  analyticsDescription,
  marketingTitle,
  marketingDescription,
  dialogLabel = "Cookies",
  showAnalytics = true,
  showMarketing = false,
  hidden = false,
}: CookieBannerProps) {
  const [visible, setVisible] = useState(false)
  const [draft, setDraft] = useState<ConsentState>(DEFAULT_CONSENT)

  const evaluate = useCallback(() => {
    const stored = localStorage.getItem(consentKey)
    if (stored) {
      const parsed = deserialize(stored)
      if (parsed) {
        applyConsent(parsed)
        setDraft(parsed)
        setVisible(false)
        return
      }
    }
    applyConsent(DEFAULT_CONSENT)
    setDraft(DEFAULT_CONSENT)
    setVisible(true)
  }, [consentKey])

  useEffect(() => {
    evaluate()
    const onStorage = (e: StorageEvent) => {
      if (e.key === consentKey) evaluate()
    }
    const onManage = () => {
      const stored = localStorage.getItem(consentKey)
      setDraft(stored ? (deserialize(stored) ?? DEFAULT_CONSENT) : DEFAULT_CONSENT)
      setVisible(true)
    }
    window.addEventListener("storage", onStorage)
    window.addEventListener(manageEvent, onManage)
    return () => {
      window.removeEventListener("storage", onStorage)
      window.removeEventListener(manageEvent, onManage)
    }
  }, [evaluate, consentKey, manageEvent])

  const acceptAll = () => {
    const state: ConsentState = { necessary: true, analytics: true, marketing: true }
    localStorage.setItem(consentKey, serialize(state))
    applyConsent(state)
    setVisible(false)
  }

  const rejectAll = () => {
    const state: ConsentState = { necessary: true, analytics: false, marketing: false }
    localStorage.setItem(consentKey, serialize(state))
    applyConsent(state)
    setVisible(false)
  }

  const acceptSelection = () => {
    localStorage.setItem(consentKey, serialize(draft))
    applyConsent(draft)
    setVisible(false)
  }

  if (hidden || !visible) return null

  return (
    <div
      role="dialog"
      aria-label={dialogLabel}
      aria-live="polite"
      className={cn(
        "fixed inset-x-0 bottom-0 z-[60] p-4 sm:p-6",
        "animate-in slide-in-from-bottom-4 fade-in duration-300",
      )}
    >
      <div className="container-premium">
        <div className="flex flex-col gap-4 rounded-xl border border-border bg-background p-5 shadow-lg">
          <p className="max-w-2xl text-sm leading-relaxed text-foreground">
            {text}{" "}
            <a
              href={privacyHref}
              className="font-semibold text-primary underline underline-offset-2"
            >
              {policyLabel}
            </a>
          </p>

          {(showAnalytics || showMarketing) ? (
            <div className="space-y-3">
              <label className="flex cursor-not-allowed items-start gap-3 opacity-70">
                <input
                  type="checkbox"
                  checked
                  disabled
                  className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                />
                <div>
                  <p className="text-sm font-semibold text-foreground">
                    {necessaryTitle}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {necessaryDescription}
                  </p>
                </div>
              </label>

              {showAnalytics && (
                <label className="flex cursor-pointer items-start gap-3">
                  <input
                    type="checkbox"
                    checked={draft.analytics}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        analytics: e.target.checked,
                      }))
                    }
                    className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                  />
                  <div>
                    <p className="text-sm font-semibold text-foreground">
                      {analyticsTitle}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {analyticsDescription}
                    </p>
                  </div>
                </label>
              )}

              {showMarketing && (
                <label className="flex cursor-pointer items-start gap-3">
                  <input
                    type="checkbox"
                    checked={draft.marketing}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        marketing: e.target.checked,
                      }))
                    }
                    className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                  />
                  <div>
                    <p className="text-sm font-semibold text-foreground">
                      {marketingTitle}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {marketingDescription}
                    </p>
                  </div>
                </label>
              )}
            </div>
          ) : null}

          <div className="flex flex-wrap gap-3">
            <button
              type="button"
              onClick={acceptAll}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-3 focus-visible:ring-primary/40"
            >
              {acceptAllLabel}
            </button>
            {(showAnalytics || showMarketing) && (
              <button
                type="button"
                onClick={acceptSelection}
                className="inline-flex h-10 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40"
              >
                {acceptSelectionLabel}
              </button>
            )}
            <button
              type="button"
              onClick={rejectAll}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40"
            >
              {rejectLabel}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { Globe, Check } from "lucide-react"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"

export interface LanguageSwitcherProps {
  locale: string
  locales: string[]
  localeNames: Record<string, string>
  localeShort: Record<string, string>
  ariaLabel?: string
  className?: string
}

export function LanguageSwitcher({
  locale,
  locales,
  localeNames,
  localeShort,
  ariaLabel = "Language",
  className,
}: LanguageSwitcherProps) {
  const pathname = usePathname()
  const pathnameWithoutLocale =
    pathname.replace(new RegExp(`^/(${locales.join("|")})`), "") || ""

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={ariaLabel}
        className={cn(
          "inline-flex items-center gap-1 rounded-md px-2.5 py-2 text-sm font-medium text-foreground/80 outline-none transition-colors hover:text-primary focus-visible:ring-2 focus-visible:ring-ring",
          className,
        )}
      >
        <Globe className="h-4 w-4" aria-hidden="true" />
        <span>{localeShort[locale] ?? locale.toUpperCase()}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        {locales.map((l) => (
          <DropdownMenuItem key={l} asChild className="justify-between">
            <Link href={`/${l}${pathnameWithoutLocale}`}>
              {localeNames[l] ?? l}
              {l === locale && (
                <Check className="h-4 w-4 text-primary" aria-hidden="true" />
              )}
            </Link>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { Menu, X, ChevronDown } from "lucide-react"
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from "@/components/ui/sheet"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { CtaExternal } from "@/components/ui/cta-button"
import { LanguageSwitcher } from "@/components/navigation/language-switcher"
import { cn } from "@/lib/utils"

export interface NavItem {
  label: string
  href: string
  children?: NavItem[]
}

export interface NavbarProps {
  logo: { src?: string; alt: string; href: string; initial?: string }
  items: NavItem[]
  cta: { label: string; href: string }
  locale: string
  locales: string[]
  localeNames: Record<string, string>
  localeShort: Record<string, string>
  siteName: string
  menuLabel?: string
  languageLabel?: string
  closeLabel?: string
  navLabel?: string
  mobileNavLabel?: string
}

export function Navbar({
  logo,
  items,
  cta,
  locale,
  locales,
  localeNames,
  localeShort,
  siteName,
  menuLabel = "Menu",
  languageLabel = "Language",
  closeLabel = "Close",
  navLabel = "Main navigation",
  mobileNavLabel = "Mobile navigation",
}: NavbarProps) {
  const pathname = usePathname()
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8)
    onScroll()
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  const isActive = (href: string) => {
    if (href === `/${locale}`) return pathname === `/${locale}`
    return pathname.startsWith(href)
  }

  return (
    <header
      className={cn(
        "sticky top-0 z-50 w-full border-b transition-colors",
        scrolled
          ? "border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80"
          : "border-transparent bg-background",
      )}
    >
      <div className="container-premium flex h-16 items-center justify-between gap-4 lg:h-20">
        <Link
          href={logo.href}
          className="flex items-center gap-2 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {logo.src ? (
            <img src={logo.src} alt={logo.alt} className="h-9 w-auto" />
          ) : (
            <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary text-sm font-bold text-primary-foreground">
              {logo.initial ?? siteName.charAt(0)}
            </span>
          )}
          <span className="text-lg font-bold tracking-tight text-foreground">
            {siteName}
          </span>
        </Link>

        <nav className="hidden items-center gap-1 lg:flex" aria-label={navLabel}>
          {items.map((item) =>
            item.children && item.children.length > 0 ? (
              <DropdownMenu key={item.href}>
                <DropdownMenuTrigger
                  className={cn(
                    "inline-flex items-center gap-1 rounded-full px-4 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
                    isActive(item.href)
                      ? "bg-primary text-primary-foreground"
                      : "text-foreground hover:bg-secondary",
                  )}
                >
                  {item.label}
                  <ChevronDown className="h-4 w-4" aria-hidden="true" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="w-56">
                  {item.children.map((child) => (
                    <DropdownMenuItem key={child.href} asChild>
                      <Link href={child.href}>{child.label}</Link>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "rounded-full px-4 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
                  isActive(item.href)
                    ? "bg-primary text-primary-foreground"
                    : "text-foreground hover:bg-secondary",
                )}
                aria-current={isActive(item.href) ? "page" : undefined}
              >
                {item.label}
              </Link>
            ),
          )}
        </nav>

        <div className="flex items-center gap-2">
          <LanguageSwitcher
            locale={locale}
            locales={locales}
            localeNames={localeNames}
            localeShort={localeShort}
            ariaLabel={languageLabel}
          />

          <CtaExternal href={cta.href} className="hidden md:inline-flex">
            {cta.label}
          </CtaExternal>

          <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
            <SheetTrigger
              aria-label={menuLabel}
              className="inline-flex h-10 w-10 items-center justify-center rounded-md text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring lg:hidden"
            >
              <Menu className="h-5 w-5" aria-hidden="true" />
            </SheetTrigger>
            <SheetContent side="right" showCloseButton={false} className="w-full max-w-sm p-0">
              <SheetTitle className="sr-only">{menuLabel}</SheetTitle>
              <div className="flex items-center justify-between border-b border-border px-5 py-4">
                <span className="text-lg font-bold text-foreground">{siteName}</span>
                <button
                  type="button"
                  onClick={() => setMobileOpen(false)}
                  aria-label={closeLabel}
                  className="inline-flex h-9 w-9 items-center justify-center rounded-md text-foreground hover:bg-muted"
                >
                  <X className="h-5 w-5" aria-hidden="true" />
                </button>
              </div>
              <nav className="flex max-h-[calc(100dvh-4rem)] flex-col gap-1 overflow-y-auto px-5 py-6" aria-label={mobileNavLabel}>
                {items.map((item) => (
                  <div key={item.href}>
                    <Link
                      href={item.href}
                      onClick={() => setMobileOpen(false)}
                      className="block rounded-2xl px-4 py-3 font-medium outline-none transition-colors hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {item.label}
                    </Link>
                    {item.children?.map((child) => (
                      <Link
                        key={child.href}
                        href={child.href}
                        onClick={() => setMobileOpen(false)}
                        className="block rounded-2xl py-3 pl-8 pr-4 text-sm font-medium text-foreground/80 outline-none transition-colors hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        {child.label}
                      </Link>
                    ))}
                  </div>
                ))}
                <CtaExternal href={cta.href} size="lg" className="mt-4 w-full">
                  {cta.label}
                </CtaExternal>
              </nav>
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
  )
}

"use client"

import { cn } from "@/lib/utils"

export interface ManageCookiesButtonProps {
  label: string
  manageEvent?: string
  className?: string
}

export function ManageCookiesButton({
  label,
  manageEvent = "manage-cookies",
  className,
}: ManageCookiesButtonProps) {
  return (
    <button
      type="button"
      onClick={() => window.dispatchEvent(new Event(manageEvent))}
      className={cn(
        "text-sm text-muted-foreground transition-colors hover:text-primary",
