"use client"

import { useState } from "react"
import { SectionHeading } from "@/components/ui/section-heading"
import {
  type SectionVariant,
  sectionVariantClasses,
} from "@/lib/section-variants"
import { cn } from "@/lib/utils"

export interface FaqItem {
  question: string
  answer: string
  category?: string
}

export interface FaqListProps {
  eyebrow?: string
  title: string
  subtitle?: string
  items: FaqItem[]
  allLabel?: string
  variant?: SectionVariant
  className?: string
}

export function FaqList({
  eyebrow,
  title,
  subtitle,
  items,
  allLabel = "All",
  variant = "default",
  className,
}: FaqListProps) {
  const categories = Array.from(new Set(items.map((f) => f.category).filter(Boolean))) as string[]
  const hasCategories = categories.length > 1
  const [active, setActive] = useState<string | null>(null)
  const [openIndex, setOpenIndex] = useState<number | null>(null)

  const colors = sectionVariantClasses[variant]
  const filtered = active ? items.filter((f) => f.category === active) : items

  return (
    <section className={cn("section-padding", colors.section, className)}>
      <div className="container-premium">
        <SectionHeading eyebrow={eyebrow} title={title} subtitle={subtitle} variant={variant} />

        {hasCategories && (
          <div className="mt-8 flex flex-wrap justify-center gap-2">
            <button
              type="button"
              onClick={() => setActive(null)}
              className={cn(
                "rounded-full px-4 py-2 text-sm font-medium transition-colors",
                active === null
                  ? "bg-primary text-primary-foreground"
                  : "bg-muted text-muted-foreground hover:bg-muted/80",
              )}
            >
              {allLabel}
            </button>
            {categories.map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setActive(cat)}
                className={cn(
                  "rounded-full px-4 py-2 text-sm font-medium transition-colors",
                  active === cat
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground hover:bg-muted/80",
                )}
              >
                {cat}
              </button>
            ))}
          </div>
        )}

        <div className="mx-auto mt-10 max-w-3xl divide-y divide-border">
          {filtered.map((faq, i) => {
            const isOpen = openIndex === i
            return (
              <div key={faq.question} className="py-4">
                <button
                  type="button"
                  onClick={() => setOpenIndex(isOpen ? null : i)}
                  className="flex w-full items-center justify-between gap-4 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  aria-expanded={isOpen}
                >
                  <span className="font-medium text-foreground">{faq.question}</span>
                  <span
                    className={cn(
                      "shrink-0 text-xl transition-transform",
                      isOpen ? "text-secondary" : "text-muted-foreground",
                    )}
                    aria-hidden="true"
                  >
                    {isOpen ? "−" : "+"}
                  </span>
                </button>
                {isOpen && (
                  <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
                    {faq.answer}
                  </p>
                )}
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

import { Quote } from "lucide-react"
import { SectionHeading } from "@/components/ui/section-heading"
import { Reveal } from "@/components/ui/reveal"
import {
  type SectionVariant,
  sectionVariantClasses,
} from "@/lib/section-variants"
import { cn } from "@/lib/utils"

export interface Testimonial {
  quote: string
  name: string
  role?: string
  company?: string
}

export interface TestimonialsProps {
  eyebrow?: string
  title: string
  subtitle?: string
  items: Testimonial[]
  variant?: SectionVariant
  className?: string
}

export function Testimonials({
  eyebrow,
  title,
  subtitle,
  items,
  variant = "default",
  className,
}: TestimonialsProps) {
  const colors = sectionVariantClasses[variant]
  const isDark = variant === "primary" || variant === "secondary"

  return (
    <section className={cn("section-padding", colors.section, className)}>
      <div className="container-premium">
        <SectionHeading eyebrow={eyebrow} title={title} subtitle={subtitle} variant={variant} />
        <div className="mt-12 grid gap-8 md:grid-cols-2 lg:grid-cols-3">
          {items.map((t, i) => (
            <Reveal key={t.name} delay={i * 0.1}>
              <figure className={cn("flex h-full flex-col rounded-xl border p-6 shadow-sm", colors.card, colors.cardBorder)}>
                <Quote className={cn("mb-4 h-8 w-8 opacity-20", isDark ? "text-primary-foreground" : "text-secondary")} aria-hidden="true" />
                <blockquote className={cn("flex-1 text-sm leading-relaxed", colors.heading)}>
                  &ldquo;{t.quote}&rdquo;
                </blockquote>
                <figcaption className={cn("mt-6 border-t pt-4", colors.cardBorder)}>
