          ))}
        </div>
      </div>
    </section>
  )
}

import { SectionHeading } from "@/components/ui/section-heading"
import {
  type SectionVariant,
  sectionVariantClasses,
} from "@/lib/section-variants"
import { cn } from "@/lib/utils"

export interface PricingItem {
  code?: string
  name: string
  description?: string
  duration?: string
  price: string
}

export const DEFAULT_PRICING_COLUMNS = {
  code: "Code",
  name: "Service",
  description: "Description",
  duration: "Duration",
  price: "Price",
}

interface PricingTableProps {
  eyebrow?: string
  title: string
  subtitle?: string
  items: PricingItem[]
  insuranceNote?: string
  cancellationNote?: string
  columns?: Partial<typeof DEFAULT_PRICING_COLUMNS>
  variant?: SectionVariant
  className?: string
}

export function PricingTable({
  eyebrow,
  title,
  subtitle,
  items,
  insuranceNote,
  cancellationNote,
  columns,
  variant = "default",
  className,
}: PricingTableProps) {
  const colors = sectionVariantClasses[variant]
  const cols = { ...DEFAULT_PRICING_COLUMNS, ...columns }

  const hasCode = items.some((i) => i.code)
  const hasDuration = items.some((i) => i.duration)
  const hasDescription = items.some((i) => i.description)

  return (
    <section className={cn("section-padding", colors.section, className)}>
      <div className="container-premium">
        <SectionHeading eyebrow={eyebrow} title={title} subtitle={subtitle} variant={variant} />
        <div className="mx-auto mt-10 max-w-4xl overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b-2 border-secondary">
                {hasCode && (
                  <th className="px-4 py-3 font-semibold text-foreground">{cols.code}</th>
                )}
                <th className="px-4 py-3 font-semibold text-foreground">{cols.name}</th>
                {hasDescription && (
                  <th className="hidden px-4 py-3 font-semibold text-foreground md:table-cell">
                    {cols.description}
                  </th>
                )}
                {hasDuration && (
                  <th className="px-4 py-3 font-semibold text-foreground">{cols.duration}</th>
                )}
                <th className="px-4 py-3 text-right font-semibold text-foreground">
                  {cols.price}
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {items.map((item) => (
                <tr key={item.name} className="transition-colors hover:bg-muted/50">
                  {hasCode && (
                    <td className="px-4 py-3 font-mono text-xs text-muted-foreground">
                      {item.code}
                    </td>
                  )}
                  <td className="px-4 py-3 font-medium text-foreground">{item.name}</td>
                  {hasDescription && (
                    <td className="hidden px-4 py-3 text-muted-foreground md:table-cell">
                      {item.description}
                    </td>
                  )}
                  {hasDuration && (
                    <td className="px-4 py-3 text-muted-foreground">{item.duration}</td>
                  )}
                  <td className="px-4 py-3 text-right font-semibold text-foreground">
                    {item.price}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {(insuranceNote || cancellationNote) && (
          <div className="mx-auto mt-6 max-w-4xl space-y-2 text-sm text-muted-foreground">
            {insuranceNote && <p>{insuranceNote}</p>}
            {cancellationNote && <p>{cancellationNote}</p>}
          </div>
        )}
      </div>
    </section>
  )
}

import { MapPin, Phone, Mail, Clock } from "lucide-react"
import { type SocialPlatform, socialIconMap } from "@/components/ui/social-icons"
import {
  type SectionVariant,
  sectionVariantClasses,
} from "@/lib/section-variants"
import { cn } from "@/lib/utils"

export interface ContactInfoProps {
  title?: string
  address?: string
  mapsUrl?: string
  mapsEmbed?: string
  phone?: string
  email?: string
  hours?: { label: string; value: string }[]
  socials?: { platform: SocialPlatform; url: string }[]
  hoursLabel?: string
  mapPlaceholder?: string
  mapsTitle?: string
  variant?: SectionVariant
  className?: string
}

export function ContactInfo({
  title,
  address,
  mapsUrl,
  mapsEmbed,
  phone,
  email,
  hours,
  socials,
  hoursLabel = "Hours",
  mapPlaceholder,
  mapsTitle = "Google Maps",
  variant = "default",
  className,
}: ContactInfoProps) {
  const colors = sectionVariantClasses[variant]

  return (
    <section className={cn("section-padding", colors.section, className)}>
      <div className="container-premium">
        <div className="grid gap-12 lg:grid-cols-2">
          <div className="space-y-8">
            {title && (
              <h2 className="font-heading text-3xl font-bold text-foreground">{title}</h2>
            )}

            <div className="space-y-5">
              {address && (
                <div className="flex items-start gap-3">
                  <MapPin className="mt-1 h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                  {mapsUrl ? (
                    <a
                      href={mapsUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-foreground transition-colors hover:text-primary"
                    >
                      {address}
                    </a>
                  ) : (
                    <span className="text-foreground">{address}</span>
                  )}
                </div>
              )}

              {phone && (
                <div className="flex items-center gap-3">
                  <Phone className="h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                  <a
                    href={`tel:${phone.replace(/\s/g, "")}`}
                    className="text-foreground transition-colors hover:text-primary"
                  >
                    {phone}
                  </a>
                </div>
              )}

              {email && (
                <div className="flex items-center gap-3">
                  <Mail className="h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                  <a
                    href={`mailto:${email}`}
                    className="text-foreground transition-colors hover:text-primary"
                  >
                    {email}
                  </a>
                </div>
              )}
            </div>

            {hours && hours.length > 0 && (
              <div>
                <div className="mb-3 flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-foreground">
                  <Clock className="h-4 w-4" aria-hidden="true" />
                  {hoursLabel}
                </div>
                <dl className="space-y-1.5 text-sm">
                  {hours.map((h) => (
                    <div key={h.label} className="flex justify-between gap-4">
                      <dt className="text-muted-foreground">{h.label}</dt>
                      <dd className="font-medium text-foreground">{h.value}</dd>
                    </div>
                  ))}
                </dl>
              </div>
            )}

            {socials && socials.length > 0 && (
              <div className="flex gap-3">
                {socials.map((s) => {
                  const Icon = socialIconMap[s.platform]
                  return (
                    <a
                      key={s.platform}
                      href={s.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-muted-foreground transition-colors hover:text-primary"
                      aria-label={s.platform}
                    >
                      <Icon className="h-5 w-5" />
                    </a>
                  )
                })}
              </div>
            )}
          </div>

          <div className="overflow-hidden rounded-xl bg-muted">
            {mapsEmbed ? (
              <iframe
                src={mapsEmbed}
                width="100%"
                height="100%"
                style={{ border: 0, minHeight: 400 }}
                allowFullScreen
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                title={mapsTitle}
              />
            ) : (
              <div className="flex h-full min-h-[400px] items-center justify-center">
                <p className="p-12 text-center text-sm text-muted-foreground">
                  {mapPlaceholder}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}

import { cn } from "@/lib/utils"

export interface LegalSection {
  title: string
  content: string
}

export interface LegalPageProps {
  title: string
  updatedAt?: string
  updatedLabel?: string
  dateSeparator?: string
  intro?: string
  sections: LegalSection[]
  className?: string
}

export function LegalPage({
  title,
  updatedAt,
  updatedLabel = "Last updated",
  dateSeparator = " : ",
  intro,
  sections,
  className,
}: LegalPageProps) {
  return (
    <article className={cn("section-padding", className)}>
      <div className="container-premium">
        <div className="mx-auto max-w-3xl">
          <h1 className="font-heading text-3xl font-bold text-foreground sm:text-4xl">{title}</h1>
          {updatedAt && (
            <p className="mt-2 text-sm text-muted-foreground">
              {updatedLabel}{dateSeparator}{updatedAt}
            </p>
          )}
          {intro && (
            <p className="mt-6 text-lg leading-relaxed text-muted-foreground">{intro}</p>
          )}
          <div className="mt-10 space-y-10">
            {sections.map((section) => (
              <section key={section.title}>
                <h2 className="mb-4 text-xl font-semibold text-foreground">{section.title}</h2>
